  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Lakanto Affiliate Program', 'https://www.lakanto.com/pages/affiliate-application', 'https://www.lakanto.com/pages/affiliate-application', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.lakanto.com/pages/affiliate-application', 'official_site', 'affiliate', 'Lakanto''s own affiliate application page (fetched directly) states affiliates ''Earn up to 20% (based on performance)'', audiences get discount codes of up to 15% off, affiliates can receive free product and collaborative opportunities (bundles, landing pages, social content, recipes, giveaways); the brand looks for creators with 10K+ on social platforms and describes the program as ''relatively small''; the page footer lists Orem, UT 84057 and info@lakanto.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theaffiliateslist.com/keto-affiliate-programs/', 'affiliate_network', 'affiliate', 'A third-party keto affiliate guide reports Lakanto''s program runs on Refersion at up to 15% commission with a 90-day cookie; the ''up to 15%'' figure conflicts with the ''up to 20%'' ceiling on the brand''s own page, so no single rate is recorded.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.lakanto.com/pages/affiliate-application', 'official_site', 'compensation', 'No earnings-cap statement appears anywhere on the brand''s own program page, so commission_cap is recorded as unknown; an ''up to X%'' figure is a rate ceiling, not evidence of an uncapped program.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 11, 13, 8, 4, '{"niche_fit": "Sugar-free sweetener and baking products are staple demo content for keto, low-sugar and healthy-recipe creators on TikTok and Instagram.", "ugc_evidence": "The brand''s own page builds the program around creator content \u2014 social content, recipes, videos, bundles and giveaways \u2014 and recruits lifestyle creators directly.", "compensation": "The brand publishes a commission ceiling (up to 20% based on performance) on its own page, but third-party reporting says up to 15%, so the rate is recorded as null with the conflict documented.", "contact_access": "A public application page on the brand''s own domain plus a published general email (info@lakanto.com) \u2014 top band.", "opportunity_availability": "Applications are publicly open on the official site, though the brand asks for a substantial audience (10K+ on social) and reviews applications selectively.", "credibility": "Established sweetener brand owned by Saraya with national grocery distribution and a US base in Orem, Utah."}'::jsonb);
