  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PlantFusion Affiliate Program', 'https://plantfusion.com/pages/plantfusion-affiliate-program', 'https://plantfusion.com/pages/plantfusion-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://plantfusion.com/pages/plantfusion-affiliate-program', 'official_site', 'affiliate', 'PlantFusion''s own affiliate program page states a 15% base commission on all referred sales with lifetime customer association (commission on all future orders of a referred customer), a community code giving 25% off first orders, payment via PayPal 30 days after conversion, an average order value of $60+, and eligibility limited to creators 18+ based in the continental US; no network platform is named on the page.', 'verified', now());
