  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 14, 11, 9, 4, '{"niche_fit": "Plant-based protein and wellness powders are core smoothie, fitness and vegan-lifestyle creator content.", "ugc_evidence": "The brand runs its own affiliate page with a community discount code model built for creator sharing, though no large public creator program is showcased.", "compensation": "A single consistent first-party rate \u2014 15% base commission with lifetime customer association \u2014 published on the brand''s own program page.", "contact_access": "A public program/application page on the brand''s own domain; no public program email was found on the fetched page.", "opportunity_availability": "The program page is publicly open to US-based creators 18+, with terms (PayPal payout 30 days after conversion) published up front.", "credibility": "Long-running plant-based nutrition brand sold through its own store and health-food retail channels."}'::jsonb);
