  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.naturemade.com/pages/affiliates', 'official_site', 'affiliate', 'Nature Made''s own affiliates page (fetched directly) states ''Affiliates earn a commission on all referred sales to NatureMade.com'' and its sign-up link routes to signup.cj.com, confirming the program runs on CJ Affiliate; the brand''s own page publishes no rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.naturemade.com/pages/affiliates', 'affiliate_network', 'compensation', 'Third-party sources conflict on the rate (8%, 10% and 15% all appear, one attributing the program to Impact despite the brand''s own CJ sign-up link), so commission_rate is recorded as null with the conflict documented here.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.naturemade.com/pages/affiliates', 'listing', 'ugc_collab', 'Rateful''s TikTok Shop analysis reported that roughly 93% of Nature Made''s estimated TikTok Shop sales in the 30 days to Nov 6, 2026 came through affiliate creators — evidence the brand''s sales are heavily creator-driven.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 8, 10, 9, 5, '{"niche_fit": "Mainstream vitamins and supplements are everyday wellness-creator content, and the brand is a top TikTok Shop supplement seller through creators.", "ugc_evidence": "Independent TikTok Shop analysis attributes the overwhelming majority of the brand''s recent TikTok Shop sales to affiliate creators, on top of its CJ program.", "compensation": "A commission on all referred sales is confirmed on the brand''s own page, but no rate is published there and third-party figures conflict (8/10/15%), so the rate stays null.", "contact_access": "A public affiliates page on the brand''s own domain routing to the CJ sign-up; no public program email was found.", "opportunity_availability": "Open application route via the brand''s own affiliates page into CJ Affiliate.", "credibility": "Pharmavite brand founded in 1971 and marketed as the #1 pharmacist-recommended vitamin brand in the US, with national retail distribution."}'::jsonb);
