  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Adagio Teas Creator Program + CJ Affiliate Program', 'https://www.adagio.com/pages/creator_program.html', 'https://www.adagio.com/pages/creator_program.html', 'unverified', 'ugc');
