  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 12, 11, 9, 4, '{"niche_fit": "Loose-leaf tea, brewing rituals and teaware are steady food-drink and cozy-lifestyle creator content.", "ugc_evidence": "A first-party flat-fee creator program for short-form video with published pay tiers, on top of the affiliate program \u2014 unusually concrete creator evidence.", "compensation": "Published pay exists on the brand''s own pages (flat per-video tiers of roughly $100-$600 and up to 10% affiliate commission in the US), but affiliate rates conflict by region (up to 5% UK/EU), so the percentage rate is null.", "contact_access": "Two public first-party routes on the brand''s own domain \u2014 a creator program page and an affiliates page.", "opportunity_availability": "Both the creator program and the CJ affiliate program are publicly reachable from the brand''s own site.", "credibility": "Established US online tea retailer selling direct from origin farms through its own storefronts in the US, UK and EU."}'::jsonb);
