  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://af.secomapp.com/apollo-scooters/register_aff', 'official_site', 'affiliate', 'Apollo''s own affiliate registration page describes the ''Apollo Affiliate & Creator Program'': commission is a flat rate per item - $4 on non-scooter orders and a flat rate on scooters (amount not stated) - applications are reviewed rather than auto-approved, and affiliates invoice monthly.', 'verified', now());
