  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/case-study/apollo-scooters/', 'listing', 'ugc_collab', 'An UpPromote case study on Apollo reports two affiliate contribution tiers and 1,000+ affiliates, with affiliate sales making up 15-20% of revenue - a four-figure affiliate count, so saturation is not low.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 15, 6, 8, 6, 4, '{"niche_fit": "Performance e-scooters are a natural fit for tech-review and urban-mobility creators.", "ugc_evidence": "The programme is explicitly branded an ''Affiliate & Creator Program'' and the brand recruits reviewers and vloggers, with a published case study on its affiliate channel.", "compensation": "Pay is a flat rate per item ($4 on non-scooter orders; the scooter amount is not published) and regional pages conflict (4% in Canada, 8% in one listing), so no rate is recorded and compensation scores low.", "contact_access": "Access is through the brand''s own application form; no public partnerships email was found.", "opportunity_availability": "Application-based with manual approval and monthly self-invoicing, which adds friction versus instant network programmes.", "credibility": "Established Canadian scooter brand with a documented, revenue-bearing affiliate programme."}'::jsonb);
